<?php
declare(strict_types=1);
require dirname(__DIR__,2).'/includes/bootstrap.php';
require_permission('vendors.kyc.approve');
$pdo=db();
if(is_post()){
 verify_csrf();
 try{$id=(int)input('vendor_id');$decision=strtoupper((string)input('decision','PENDING'));$reason=trim((string)input('reason'));$commission=(float)input('commission_rate',0);$rule=trim((string)input('commission_rule'));if($id<1||!in_array($decision,['PENDING','APPROVE','REJECT'],true))throw new InvalidArgumentException('Invalid verification decision.');if($decision==='REJECT'&&$reason==='')throw new InvalidArgumentException('Rejection reason is required.');$v=$pdo->prepare('SELECT * FROM vendors WHERE id=?');$v->execute([$id]);$vendor=$v->fetch();if(!$vendor)throw new RuntimeException('Vendor not found.');if($decision==='APPROVE'){if(($vendor['mobile_otp_verified']??0)!=1||($vendor['kyc_status']??'')!=='VERIFIED'||($vendor['bank_verification_status']??'')!=='VERIFIED'||trim((string)($vendor['identity_proof_path']??''))===''||trim((string)($vendor['address_proof_path']??''))===''||trim((string)($vendor['cancelled_cheque_path']??''))===''||trim((string)($vendor['bank_account_number']??''))===''||trim((string)($vendor['bank_ifsc']??''))===''||$commission<=0||$commission>100)throw new InvalidArgumentException('Approval blocked: OTP, KYC, bank verification, documents and commission rate must be complete.');$newStatus='ACTIVE';$kyc='VERIFIED';}else{$newStatus=$decision==='REJECT'?'REJECTED':'PENDING_APPROVAL';$kyc=$decision==='REJECT'?'REJECTED':($vendor['kyc_status']??'PENDING');}$pdo->prepare('UPDATE vendors SET commission_rate=?,commission_rule=?,kyc_status=?,status=?,onboarding_notes=CASE WHEN ?<>"" THEN CONCAT(COALESCE(onboarding_notes,""),"\n",?) ELSE onboarding_notes END WHERE id=?')->execute([$commission,$rule?:null,$kyc,$newStatus,$reason,$reason,$id]);audit_log((int)admin()['id'],'VENDOR_'.$decision,'vendors',(string)$id,['reason'=>$reason,'commission_rate'=>$commission]);flash('success','Vendor '.$vendor['vendor_code'].' updated: '.$newStatus.'.');}catch(Throwable $e){flash('error',$e->getMessage());}redirect('/admin/vendors/verification.php?vendor_id='.(int)input('vendor_id'));}
$vendors=$pdo->query("SELECT id,vendor_code,name,shop_name,status,kyc_status,bank_verification_status FROM vendors WHERE status IN ('DRAFT','PENDING_KYC','PENDING_BANK','PENDING_APPROVAL','REJECTED','INACTIVE') OR kyc_status IN ('PENDING','REJECTED') ORDER BY created_at DESC")->fetchAll();$id=(int)input('vendor_id');$vendor=null;$summary=['sales'=>0,'bonus'=>0,'requested'=>0,'withdrawn'=>0];if($id){$s=$pdo->prepare('SELECT * FROM vendors WHERE id=?');$s->execute([$id]);$vendor=$s->fetch();if($vendor){$q=$pdo->prepare('SELECT COALESCE(SUM(bill_amount),0) sales,COALESCE(SUM(promo_amount),0) bonus FROM merchant_settlements WHERE merchant_id=?');$q->execute([$id]);$summary=array_merge($summary,$q->fetch()?:[]);$q=$pdo->prepare("SELECT COALESCE(SUM(amount),0) requested,COALESCE(SUM(CASE WHEN status='PAID' THEN amount ELSE 0 END),0) withdrawn FROM vendor_payout_requests WHERE vendor_id=?");try{$q->execute([$id]);$summary=array_merge($summary,$q->fetch()?:[]);}catch(Throwable $e){}}}$pageTitle='Vendor verification & activation';$pageSubtitle='Self-registered vendor review, financial checks and controlled activation';require APP_ROOT.'/includes/header.php';
?><section class="panel"><div class="panel-head"><div><h2>Vendor verification queue</h2><p class="help">Only approved KYC administrators can activate a vendor account.</p></div></div><div class="table-wrap"><table><thead><tr><th>Vendor</th><th>Shop</th><th>KYC</th><th>Bank</th><th>Status</th><th>Review</th></tr></thead><tbody><?php foreach($vendors as $row):?><tr><td><strong><?=e($row['vendor_code'])?></strong><br><?=e($row['name'])?></td><td><?=e($row['shop_name'])?></td><td><span class="badge <?=strtolower(e($row['kyc_status']))?>"><?=e($row['kyc_status'])?></span></td><td><span class="badge <?=strtolower(e($row['bank_verification_status']??'PENDING'))?>"><?=e($row['bank_verification_status']??'PENDING')?></span></td><td><?=e($row['status'])?></td><td><a class="btn small secondary" href="?vendor_id=<?=e($row['id'])?>">View &amp; verify</a></td></tr><?php endforeach?></tbody></table><?php if(!$vendors):?><div class="empty">No vendors are waiting for verification.</div><?php endif?></div></section><?php if($vendor):?><section class="panel"><div class="panel-head"><h2>Self-registered vendor review · <?=e($vendor['vendor_code'])?></h2><span class="badge pending"><?=e($vendor['status'])?></span></div><div class="grid stats"><div class="card"><span class="label">Total sales / money</span><span class="value"><?=money($summary['sales'])?></span></div><div class="card"><span class="label">Total bonus amount</span><span class="value"><?=money($summary['bonus'])?></span></div><div class="card"><span class="label">Money requested</span><span class="value"><?=money($summary['requested'])?></span></div><div class="card"><span class="label">Withdrawal done</span><span class="value"><?=money($summary['withdrawn'])?></span></div></div><div class="grid detail-grid"><div><h3>Business &amp; owner profile</h3><div class="kv"><span>Business</span><strong><?=e($vendor['shop_name'])?></strong></div><div class="kv"><span>Owner</span><strong><?=e($vendor['owner_name']??$vendor['name'])?></strong></div><div class="kv"><span>Mobile</span><strong><?=e($vendor['mobile']?:'—')?></strong></div><div class="kv"><span>Email</span><strong><?=e($vendor['email']?:'—')?></strong></div><div class="kv"><span>Category</span><strong><?=e($vendor['business_category']??'—')?></strong></div><div class="kv"><span>Address</span><strong><?=e($vendor['address']?:'—')?></strong></div><?php foreach(['logo_path'=>'Shop logo','identity_proof_path'=>'Identity document','gstin'=>'GST / shop certificate','cancelled_cheque_path'=>'Cancelled cheque'] as $field=>$label):?><div class="kv"><span><?=e($label)?></span><strong><?php if($field==='gstin'):?><?=e($vendor[$field]?:'—')?><?php elseif($vendor[$field]):?><a class="btn small secondary" target="_blank" rel="noopener" href="<?=e($vendor[$field])?>">View</a><?php else:?>Not supplied<?php endif?></strong></div><?php endforeach?></div><div><h3>Bank &amp; commission</h3><div class="kv"><span>Account holder</span><strong><?=e($vendor['bank_account_holder']?:'—')?></strong></div><div class="kv"><span>Account number</span><strong><?=e(mask_account($vendor['bank_account_number']??null))?></strong></div><div class="kv"><span>IFSC / branch</span><strong><?=e($vendor['bank_ifsc']?:'—')?> / <?=e($vendor['bank_branch']?:'—')?></strong></div><div class="kv"><span>UPI ID</span><strong><?=e($vendor['settlement_upi']?:'—')?></strong></div><div class="kv"><span>Commission</span><strong><?=e(number_format((float)$vendor['commission_rate'],2))?>%</strong></div><div class="kv"><span>Verification</span><strong>KYC <?=e($vendor['kyc_status']??'PENDING')?> · Bank <?=e($vendor['bank_verification_status']??'PENDING')?></strong></div><form method="post" class="stack"><?=csrf_field()?><input type="hidden" name="vendor_id" value="<?=e($vendor['id'])?>"><label>Commission rate (%)<input name="commission_rate" type="number" min="0" max="100" step="0.01" value="<?=e($vendor['commission_rate'])?>" required></label><label>Custom commission rule<input name="commission_rule" value="<?=e($vendor['commission_rule']??'')?>"></label><label>Decision<select name="decision"><option>PENDING</option><option>APPROVE</option><option>REJECT</option></select></label><label>Reason / admin note<textarea name="reason" placeholder="Required when rejecting"></textarea></label><button class="btn success" type="submit">Save &amp; activate / record decision</button></form></div></div></section><?php endif?><?php require APP_ROOT.'/includes/footer.php';
